package com.bank.locker.service;

import java.util.logging.Logger;

// Finds the single duplicate reference using Floyd's cycle detection on indices.
public class DuplicateRefFinder {
    private static final Logger log = Logger.getLogger(DuplicateRefFinder.class.getName());

    public int findDuplicate(int[] refs) {
        // Phase 1: find the meeting point treating values as next-index jumps.
        int slow = refs[0];
        int fast = refs[0];
        do {
            slow = refs[slow];            // one jump
            fast = refs[refs[fast]];      // two jumps
        } while (slow != fast);

        // Phase 2: reset one pointer to the start, advance both by one jump.
        int ptr = refs[0];
        while (ptr != slow) {
            ptr = refs[ptr];
            slow = refs[slow];
        }
        final int dup = ptr;
        log.warning(() -> "Duplicate locker reference = " + dup);
        return ptr;
    }
}
