package com.bank.locker;

import com.bank.locker.service.DuplicateRefFinder;
import java.util.Arrays;
import java.util.logging.Logger;

public class DuplicateRefDemo {
    private static final Logger log = Logger.getLogger(DuplicateRefDemo.class.getName());

    public static void main(String[] args) {
        // n+1 references in range 1..n, exactly one duplicated (here 2).
        int[] refs = {1, 3, 4, 2, 2};
        log.info(() -> "Locker references: " + Arrays.toString(refs));

        DuplicateRefFinder finder = new DuplicateRefFinder();
        int duplicate = finder.findDuplicate(refs);

        log.info(() -> "The duplicated reference is " + duplicate);
    }
}
